def _patch_orchestrator_screen(monkeypatch, screen, *, phase='field'):
    monkeypatch.setattr(orchestrator, 'classify', lambda _frame: phase)
    monkeypatch.setattr(screen_mod, 'parse', lambda _frame, phase='field': screen)


def test_ch9_field_recall_skips_when_sortie_owns_field_or_month_sub(monkeypatch):
    camp = {'target': (40, 40), 'clipped': False, 'kind': 'tent'}
    monkeypatch.setattr(recall_flow, 'own_camps', lambda _frame: [dict(camp)])
    _patch_orchestrator_screen(
        monkeypatch,
        screen_mod.Screen([], None, '', kind='map', cursor=(10, 10)),
    )

    # 1. With active sortie_attempt confirmation, ch9_field_recall must stay off.
    state_sortie = {
        'step': 10,
        'policy': {
            'chapter': 9,
            'month': '91-8',
            'tick': 100,
            'captured': list(ROAD[:-1]),
            'world': {'garrison': {'イデ！': ['どうし']}},
            'flow': {'sortie_attempt': {'step': 'I:c9:1', 'confirmation_tick': 95}},
        },
    }
    _, updated_sortie = orchestrator.decide(BLANK_FRAME, state_sortie)
    assert 'recall' not in _flow(updated_sortie['policy'])
    assert not any(r['decision'] == 'camp_found' for r in updated_sortie['_records'])

    # 2. With active month_sub, ch9_field_recall must stay off.
    state_month = {
        'step': 11,
        'policy': {
            'chapter': 9,
            'month': '91-8',
            'tick': 101,
            'captured': list(ROAD[:-1]),
            'world': {'garrison': {'イデ！': ['どうし']}},
            'month_sub': {'kind': 'recruit'},
        },
    }
    _, updated_month = orchestrator.decide(BLANK_FRAME, state_month)
    assert 'recall' not in _flow(updated_month['policy'])
    assert not any(r['decision'] == 'camp_found' for r in updated_month['_records'])

    # 3. With neither active, ch9_field_recall still starts normally.
    state_idle = {
        'step': 12,
        'policy': {
            'chapter': 9,
            'month': '91-8',
            'tick': 102,
            'captured': list(ROAD[:-1]),
            'world': {'garrison': {'イデ！': ['どうし']}},
        },
    }
    actions_idle, updated_idle = orchestrator.decide(BLANK_FRAME, state_idle)
    assert _flow(updated_idle['policy']).get('recall', {}).get('stage') == 'to_camp'
    assert actions_idle


def test_recall_fort_menu_not_closed_by_close_panel_even_during_sortie_yield(monkeypatch):
    # #4938 / #4942: camp_enter opened a 砦 menu (しゅつげき/こうかん) while
    # _sortie_owns_the_field was True. orchestrator must hand it to
    # camp_recall_step instead of falling through to close_panel [pad('b')].
    fort_menu = screen_mod.Screen(
        [
            screen_mod.TextLine(40, tuple((36 + 8 * i, ch) for i, ch in enumerate('しゅつげき'))),
            screen_mod.TextLine(64, tuple((36 + 8 * i, ch) for i, ch in enumerate('こうかん'))),
        ],
        (20, 36, 28, 44),
        'しゅつげき こうかん',
        kind='text',
        selected='しゅつげき',
    )
    _patch_orchestrator_screen(monkeypatch, fort_menu, phase='field_menu')

    state = {
        'step': 20,
        'policy': {
            'chapter': 10,
            'month': '44-3',
            'tick': 200,
            'captured': ['アルマムーン'],
            'flow': {
                'sortie_attempt': {'step': 'A:1:1', 'confirmation_tick': 195},
                'recall': {'stage': 'menu', 'target': [139, 114],
                           'last_seen': [139, 114], 'steps': 0},
            },
        },
    }
    actions, updated = orchestrator.decide(BLANK_FRAME, state)
    assert actions == [{'type': 'pad', 'buttons': ['a'], 'hold_ms': 100}]
    assert not any(r['decision'] == 'close_panel' for r in updated['_records'])
    recall_state = _flow(updated['policy'])['recall']
    assert recall_state['stage'] == 'fort_list'

    # Also guard subsequent frames inside FORT_STAGES (e.g. fort_status text card).
    status_card = screen_mod.Screen(
        [],
        None,
        'カイン HP 100/100',
        kind='text',
    )
    _patch_orchestrator_screen(monkeypatch, status_card, phase='field_menu')
    recall_state['stage'] = 'fort_status'
    called = []
    monkeypatch.setattr(recall_flow, 'camp_recall_step',
                        lambda _scr, _mem, _frm: called.append(True) or [])
    actions2, _ = orchestrator.decide(BLANK_FRAME, {
        'step': 21,
        'policy': updated['policy'],
    })
    assert called == [True]
    assert actions2 == []


@pytest.mark.parametrize('origin,expected_goal', [
    ((536, 416), list(chart.CH9_BOSS_WAYPOINT)),   # イデ！ pocket -> north corridor
    ((568, 212), list(chart.CH9_EAST_MOUTH)),      # north corridor -> east mouth
    ((700, 300), [810, 645]),                      # east side -> direct boss cell
])
def test_ch9_recall_y_jump_applies_cliff_detour(monkeypatch, origin, expected_goal):
    chart.set_moving_boss_cell(9, (810, 645))
    ox, oy = nav.Y_JUMP_OFFSET[9]
    monkeypatch.setattr(nav, 'world_cursor',
                        lambda _f, _ch: (origin[0] / 8 + ox, origin[1] / 8 + oy))
    monkeypatch.setattr(nav, 'world_flags', lambda _f, _ch, _c: {})
    mem = {
        'chapter': 9,
        'tick': 100,
        'y_jump': {
            'goal': BOSS, 'mode': 'target', 'step': 'RECALL',
            'moves': 0, 'wait': 0, 'tick': 100,
        },
        '_records': [],
    }
    nav._y_jump_step(mem, BLANK_FRAME)
    assert mem['y_jump']['goal_cell'] == expected_goal


def test_boss_redirect_dest_requires_ch9_y_jump_before_confirm(monkeypatch):
    chart.set_moving_boss_cell(9, (810, 645))
    monkeypatch.setattr(map_flow, '_target_roof_under_marker', lambda *a, **k: True)
    monkeypatch.setattr(recall_flow, '_start_y_jump',
                        lambda _mem, step, goal, mode: [{'jump': (step['step'], goal, mode)}])

    picker = SimpleNamespace(kind='map_target', marker=(132, 113), cursor=None,
                             hand=None, selected=None, text='')
    mem = {
        'chapter': 9,
        'tick': 500,
        'captured': list(ROAD),
        'boss_cell': {'chapter': 9, 'cell': [810, 645], 'tick': 495},
        '_records': [],
    }
    state = {'stage': 'dest', 'target': [132, 113], 'boss': True, 'goal': BOSS}

    # Before a Y jump receipt exists, _boss_redirect_dest_step must start the jump
    # so nav._y_jump_step measures origin and applies ch9_cliff_detour.
    actions1 = recall_flow._boss_redirect_dest_step(picker, mem, BLANK_FRAME, state, (132, 113))
    assert actions1 == [{'jump': ('RECALL', BOSS, 'target')}]

    # Once y_jumped['RECALL'] == BOSS, it confirms the move.
    mem['y_jumped'] = {'RECALL': BOSS}
    actions2 = recall_flow._boss_redirect_dest_step(picker, mem, BLANK_FRAME, state, (132, 113))
    assert actions2 == [{'type': 'pad', 'buttons': ['a'], 'hold_ms': 100}]


def test_general_jump_yields_to_active_ch9_boss_pursuit_candidate():
    mem = {
        'chapter': 9,
        'tick': 1000,
        '_records': [],
        'world': {
            'garrison': {'イデ！': ['どうし', 'ゼウス']},
            'sorties': {
                'A:1:1': {'general': 'カシス', 'target': BOSS, 'status': 'overdue'},
            },
        },
        bp.LIST_KEY: {
            'カシス': {'step': 'A:1:1', 'launched': 500},
        },
    }
    map_screen = SimpleNamespace(kind='map', lines=[], hand=None, selected=None,
                                 text='', marker=None, cursor=None)
    assert map_flow.general_jump_step(map_screen, mem, None) is None
    assert 'general_jump' not in mem

    # When pursuit has no eligible candidate (e.g., all generals on cooldown),
    # general_jump still arms normally.
    mem[bp.LIST_KEY]['カシス']['pursuit_tick'] = 950
    actions = map_flow.general_jump_step(map_screen, mem, None)
    assert actions == []
    assert isinstance(mem.get('general_jump'), dict)
